default.shell:
$mismatchCount = 0

$key = Get-Item -LiteralPath 'HKCU:\Software\Policies\Microsoft\Windows\CloudContent' -ErrorAction SilentlyContinue
$current = $null
if ($key) { $current = $key.GetValue('ConfigureWindowsSpotlight', $null, 'DoNotExpandEnvironmentNames') }
if (-not ($current -is [int] -and [BitConverter]::ToUInt32([BitConverter]::GetBytes($current), 0) -eq [uint32]2)) {
    Write-Output 'Mismatch: HKCU:\Software\Policies\Microsoft\Windows\CloudContent [ConfigureWindowsSpotlight]'
    $mismatchCount++
}

if ($mismatchCount -gt 0) { exit 1 }
exit 0

steps.shell:
$ErrorActionPreference = 'Stop'
trap { Write-Output $_.Exception.Message; exit 1 }

if (-not (Test-Path -LiteralPath 'HKCU:\Software\Policies\Microsoft\Windows\CloudContent')) {
    New-Item -Path 'HKCU:\Software\Policies\Microsoft\Windows\CloudContent' -Force | Out-Null
}
New-ItemProperty -LiteralPath 'HKCU:\Software\Policies\Microsoft\Windows\CloudContent' -Name 'ConfigureWindowsSpotlight' -Value 2 -PropertyType DWord -Force | Out-Null
exit 0
